const src = $json || {};
const body = src.body || {};
const headers = src.headers || {};

const cfg = {
  defaultDryRun: !!src.defaultDryRun,
  authHeaderName: String(src.authHeaderName || 'x-lt-webhook-key').toLowerCase(),
  authHeaderValue: String(src.authHeaderValue || ''),
  provider: String(src.provider || 'SimpleTexting').trim(),
  eventType: String(src.eventType || 'inbound_reply').trim(),
};

const incomingAuth = headers[cfg.authHeaderName] || headers[cfg.authHeaderName.toLowerCase()] || '';
if (cfg.authHeaderValue && incomingAuth !== cfg.authHeaderValue) {
  return [{ json: { ok: false, error: 'unauthorized', message: 'Invalid webhook auth header' } }];
}

function clean(v) { return String(v ?? '').trim(); }
function parseBoolean(v, fallback) {
  if (v === undefined || v === null || v === '') return fallback;
  if (typeof v === 'boolean') return v;
  const s = String(v).trim().toLowerCase();
  if (['true','1','yes','y'].includes(s)) return true;
  if (['false','0','no','n'].includes(s)) return false;
  return fallback;
}
function normalizePhone(v) {
  const digits = clean(v).replace(/\D/g, '');
  if (!digits) return '';
  if (digits.length === 11 && digits.startsWith('1')) return digits.slice(1);
  return digits;
}

const dryRun = parseBoolean(body.dryRun, cfg.defaultDryRun);
const from = normalizePhone(body.from || body.phone || body.mobile || body.senderPhone || body.contactPhone);
const to = normalizePhone(body.to || body.destination || body.number || body.accountPhone);
const message = clean(body.message || body.text || body.body || body.smsBody);
const providerMessageId = clean(body.smsid || body.id || body.messageId || body.message_id);
const receivedAt = clean(body.receivedAt || body.timestamp || body.createdAt || body.date || new Date().toISOString());
const contactId = clean(body.contactId || body.ghlContactId || body.externalContactId);
const conversationKey = clean(body.conversationId || body.threadId || body.externalId);
const unsubscribeKeyword = ['stop','stopall','unsubscribe','cancel','end','quit'].includes(message.toLowerCase());

if (!from) {
  return [{ json: { ok: false, error: 'missing_from_phone', message: 'Provide from/phone/mobile/senderPhone/contactPhone' } }];
}
if (!message) {
  return [{ json: { ok: false, error: 'missing_message', message: 'Provide message/text/body/smsBody' } }];
}

return [{ json: {
  ok: true,
  dryRun,
  provider: cfg.provider,
  eventType: cfg.eventType,
  from,
  to,
  message,
  providerMessageId,
  contactId,
  conversationKey,
  receivedAt,
  unsubscribeKeyword,
  rawBody: body,
  nextStep: dryRun ? 'draft_only_no_side_effects' : 'ready_for_ghl_sync_logic'
} }];
